states = {
 'ready': {'label':'Conteúdo disponível','text':'Composição principal e próximo passo.'},
 'loading': {'label':'Carregando','text':'Carregando conteúdo… título e voltar continuam disponíveis.','action':'Aguardar · sem travar navegação'},
 'error': {'label':'Erro','text':'Não foi possível concluir. Os dados preenchidos foram mantidos.','action':'Tentar novamente'},
 'empty': {'label':'Vazio','text':'Ainda não há registros para este contexto.','action':'Criar primeiro registro · se autorizado'},
 'unlinked': {'label':'Sem vínculo','text':'Nenhuma criança vinculada ou acesso indisponível. Nenhum nome alheio é exibido.','action':'Cadastrar / aceitar convite · conforme papel'},
 'insufficient': {'label':'Dados insuficientes','text':'Faltam evidências exigidas pelo instrumento. Não há nível ou score inventado.','action':'Continuar coleta de evidências'},
 'pending': {'label':'Salvamento pendente','text':'Não salvo. Sua edição permanece aberta; aguarde ou tente novamente.','action':'Tentar salvar · mesma operação'},
 'aiDown': {'label':'IA indisponível','text':'A análise não foi concluída. Seus registros confirmados estão salvos.','action':'Ver orientações gerais / tentar depois'},
 'conflict': {'label':'Conflito de edição','text':'Outra pessoa atualizou este registro. Seu rascunho foi preservado.','action':'Recarregar e comparar'},
}
screens=[dict(id=i,title=t,actor=a,blocks=b,primary=p,secondary=s) for i,t,a,b,p,s in specs]
data=dict(version='0.1',referenceDate='2026-10-22',screens=screens,states=states)
(base/'catalogo.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
md=['# Wireframes textuais — Eleva V2','', 'Documentação de baixa fidelidade. Não é aplicativo funcional. A ordem dos blocos representa leitura/foco; ações são propostas. Fonte: catálogo T01–T24 e FRDs.','', '## Fluxos para revisão','', '- Responsável: T01 → T06/T08 → T09 → T10/T15 → T11 → T12/T13 → T16/T17.','- Professor: T01 → T22 → estudante → T09/T21/T18; vínculos T07/T08.','- Criança supervisionada: T11 → T12 → T13; apoio e pausa sempre visíveis.','- Preferências: T23 acessível antes do login e pela Conta; não exige diagnóstico.','']
for s in screens:
 md += [f"## {s['id']} — {s['title']} ({s['actor']})",'', '```text',f"[Voltar]  {s['title']}",'----------------------------------------']
 md.extend(s['blocks']);md += ['----------------------------------------',f"[AÇÃO PRINCIPAL: {s['primary']}]",*('· '+x for x in s['secondary']),'```','']
md += ['## Variações de estado','', 'Aplicar à operação pertinente. O HTML permite selecionar as variações para discutir hierarquia; não significa que toda tela tenha todos os estados de negócio.','', '| Estado | Mensagem | Próxima ação |','|---|---|---|']
for state in states.values(): md.append(f"| {state['label']} | {state['text']} | {state.get('action','Ação principal da tela')} |")
md += ['', '## Notas de revisão', '', '- T05 é diálogo, com foco contido e retorno ao acionador; T12/T13 não exibem menu adulto.', '- Interface web usa navegação lateral e espaço para conteúdo; mobile usa quatro destinos e contexto infantil dedicado.', '- Tokens/cores finais e avaliações assistivas estão em 06-ux-acessibilidade.md. Wireframe não comprova contraste ou conformidade do aplicativo.', '- Os exemplos de etapas/contagens são ilustração de hierarquia, não uma rubrica ou duração pedagógica aprovada.', '- Libras, leitura e recomendações aparecem como acessos com cobertura explícita; controles ilustrados não executam esses serviços.', '']
(base/'catalogo.md').write_text('\n'.join(md),encoding='utf-8')
html='''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Eleva V2 · Wireframes para revisão</title><style>
*{box-sizing:border-box}body{margin:0;color:#172b4d;background:#f5f8fc;font:16px/1.5 system-ui,sans-serif}header,main{max-width:1500px;margin:auto;padding:24px}h1{font-size:1.8rem;margin:0 0 8px}p{max-width:90ch}a{color:#1351b4}label{display:inline-flex;gap:8px;align-items:center;flex-wrap:wrap;margin:6px 14px 6px 0}select,button{font:inherit;min-height:48px;padding:8px;border:1px solid #66788a;background:white;color:#172b4d;border-radius:4px}button{cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #0047ab;outline-offset:3px}.controls{border:1px solid #66788a;background:#fff;padding:16px;margin-top:20px}.notice{border-left:4px solid #66788a;padding:10px 16px;background:white}.board{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:24px;align-items:start}.wire{min-width:0;background:white;border:1px solid #66788a;border-radius:8px;overflow:hidden}.meta{padding:12px 16px;border-bottom:1px solid #66788a;font-size:.9rem}.phone-head{padding:16px;border-bottom:2px solid #172b4d;font-weight:700}.content{padding:16px}.block{border:1px dashed #66788a;margin-bottom:12px;padding:12px;white-space:pre-wrap;overflow-wrap:anywhere;min-height:48px}.primary{border:2px solid #172b4d;background:#edf0f3;font-weight:700;text-align:center;padding:12px;margin-top:16px;min-height:48px}.secondary{border-bottom:1px solid #66788a;padding:10px 0;min-height:48px}.state{padding:16px;border:2px solid #172b4d;background:#f5f8fc;margin-bottom:16px}.state strong{display:block}.nav{padding:12px;border-top:1px solid #66788a;font-size:.9rem}.side{display:none}.wide .board{display:block}.wide .wire{margin:0 auto 32px;max-width:1100px}.wide .layout{display:grid;grid-template-columns:190px 1fr}.wide .side{display:block;padding:16px;border-right:1px solid #66788a}.wide .layout.noSide{display:block}.wide .side div{padding:12px 0;border-bottom:1px solid #66788a}.wide .nav{display:none}.large .block,.large .primary,.large .secondary,.large .phone-head{font-size:1.3rem}.meta a{float:right}.hidden{display:none}footer{padding:24px}.count{margin:20px 0}h2{font-size:1rem;margin:0} @media(max-width:700px){header,main{padding:16px}.wide .layout{display:block}.wide .side{display:none}} @media print{.controls{display:none}.board{display:block}.wire{break-inside:avoid;margin-bottom:20px}.block{padding:7px}header{break-after:avoid}}
</style></head><body><header><h1>Eleva V2 · revisão de hierarquia</h1><p>24 wireframes de baixa fidelidade. São propostas documentais: os botões dentro das telas são representações, sem login, IA, áudio ou banco reais.</p><p><a href="../README.md">Índice da especificação</a> · <a href="catalogo.md">Versão textual</a> · <a href="../06-ux-acessibilidade.md">Regras UX e acessibilidade</a></p>
<div class="notice">Revisar próximo passo, ordem de leitura, densidade e estados. Exemplo de conteúdo não é instrumento pedagógico aprovado. Modelo visual neutro: a direção final é azul e branco, com temas/contraste definidos na especificação.</div>
<div class="controls"><label>Contexto <select id="actor"><option value="all">Todos</option><option value="responsavel">Responsável</option><option value="professor">Professor</option><option value="crianca">Criança supervisionada</option></select></label><label>Tela <select id="screen"><option value="all">Todas as telas</option></select></label><label>Estado a revisar <select id="state"></select></label><label>Composição <select id="layout"><option value="mobile">Mobile / cartões</option><option value="wide">Web / navegação lateral</option></select></label><button id="font" type="button" aria-pressed="false">Ampliar wireframes</button><p>Fluxos: <button type="button" data-flow="family">Responsável</button> <button type="button" data-flow="teacher">Professor</button> <button type="button" data-flow="child">Atividade infantil</button> <button type="button" data-flow="all">Limpar filtros</button></p></div></header>
<main><p class="count" id="count" role="status"></p><div class="board" id="board"></div></main><footer>Documento 0.1 · referência 22/10/2026. Alto contraste, leitura e Libras do produto ainda precisam de implementação e avaliação; não são comprovados por este wireframe.</footer>
<script>const data=__DATA__; const $=id=>document.getElementById(id); let flow='all'; const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flows={family:['T01','T06','T07','T08','T09','T10','T15','T11','T12','T13','T14','T16','T17','T23'],teacher:['T01','T22','T07','T08','T09','T21','T18','T15','T23'],child:['T11','T12','T13','T23']};
data.screens.forEach(s=>$('screen').add(new Option(s.id+' · '+s.title,s.id)));Object.entries(data.states).forEach(([k,v])=>$('state').add(new Option(v.label,k)));
function render(){let actor=$('actor').value,screen=$('screen').value,state=$('state').value;let list=data.screens.filter(s=>(actor==='all'||(actor==='crianca'?['T11','T12','T13','T23'].includes(s.id):(s.actor==='adulto'||s.actor===actor)))&&(screen==='all'||s.id===screen)&&(flow==='all'||flows[flow].includes(s.id)));$('count').textContent=list.length+' telas · estado: '+data.states[state].label;$('board').innerHTML=list.map(s=>{let st=data.states[state];let panel=state==='ready'?'':`<div class="state"><strong>${esc(st.label)}</strong><p>${esc(st.text)}</p><div class="primary">${esc(st.action)}</div></div>`;let hasShell=!['T01','T02','T04','T05','T08','T12','T13'].includes(s.id);let keep=['ready','pending','conflict','insufficient'].includes(state);if(state==='aiDown'&&s.id==='T15')panel+='<div class="block">Última análise revisada · data de corte e origem explícitas, se houver. Sem resultado anterior: somente orientações gerais.</div>';return `<article class="wire" id="${s.id}" aria-labelledby="h-${s.id}"><div class="meta">${esc(s.id)} · ${esc(s.actor)} <a href="#${s.id}">Link</a></div><div class="phone-head"><h2 id="h-${s.id}">[Voltar] ${esc(s.title)}</h2></div><div class="layout ${hasShell?'':'noSide'}">${hasShell?`<aside class="side" aria-label="Representação da navegação"><div>Eleva</div><div>Início</div><div>Crianças / Estudantes</div><div>Biblioteca</div><div>Conta</div></aside>`:''}<div class="content">${panel}${keep?s.blocks.map(b=>'<div class="block">'+esc(b)+'</div>').join(''):''}${state==='ready'?'<div class="primary">'+esc(s.primary)+'</div>':''}${s.secondary.map(a=>'<div class="secondary">'+esc(a)+'</div>').join('')}</div></div><div class="nav">${s.actor==='crianca'?'Contexto infantil · apoio e pausa sempre acessíveis':'Início | Crianças/Estudantes | Biblioteca | Conta'}</div></article>`}).join('');document.body.classList.toggle('wide',$('layout').value==='wide');}
['actor','screen','state','layout'].forEach(id=>$(id).addEventListener('change',render));$('font').onclick=()=>{let active=document.body.classList.toggle('large');$('font').setAttribute('aria-pressed',String(active))};document.querySelectorAll('[data-flow]').forEach(b=>b.onclick=()=>{flow=b.dataset.flow;$('actor').value='all';$('screen').value='all';render()});render();</script></body></html>'''
(base/'index.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False)),encoding='utf-8')
print(f'Gerados {len(screens)} wireframes, {len(states)} estados e catálogo textual.')
